/**
 * §11.6 weekly digest, generated by Haiku from PRE-COMPUTED stats (never the raw ledger).
 * When AI is off (cap reached, disabled, or the output fails validation) a deterministic text
 * is produced instead. Every dollar figure in the AI text must appear in the stats; otherwise
 * the AI text is discarded (the model may not invent numbers).
 */
import { z } from "zod";
import { formatMilli, formatMonth, type ISODate, type Milli, type Month } from "@homebase/shared";
import type { AiClient } from "./client";
import { textOf } from "./client";
import { redactDigits } from "./redact";

export interface DigestStats {
  weekStart: ISODate;
  weekEnd: ISODate;
  month: Month;
  /** Month-to-date spending (positive number = spent). */
  spentMtdMilli: Milli;
  /** Assigned this month. */
  assignedMtdMilli: Milli;
  overspent: { category: string; availableMilli: Milli }[];
  unapprovedCount: number;
  uncategorizedCount: number;
  unusual: { date: ISODate; payee: string; amountMilli: Milli; category: string | null; typicalMilli: Milli }[];
  newSubscriptions: { payee: string; amountMilli: Milli; cadence: string }[];
  priceChanges: { payee: string; fromMilli: Milli; toMilli: Milli }[];
  billsDue: { date: ISODate; payee: string; amountMilli: Milli }[];
  netWorth: { currentMilli: Milli; changeMilli: Milli; sinceDate: ISODate } | null;
}

export interface Digest {
  title: string;
  /** Short plain-text push notification body (≤ 180 chars). */
  pushText: string;
  /** Pinned chat message (light markdown allowed). */
  body: string;
  source: "ai" | "deterministic";
}

const DigestOutputSchema = z.object({ title: z.string(), push_text: z.string(), body: z.string() });

const DIGEST_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["title", "push_text", "body"],
  properties: {
    title: { type: "string", description: "6 words or fewer" },
    push_text: { type: "string", description: "Plain text, 180 characters or fewer" },
    body: { type: "string", description: "Short markdown summary, 120 words or fewer" },
  },
};

const DIGEST_SYSTEM = `You write the weekly money digest for a two-person household that budgets YNAB-style.
Write in a warm, brief, factual tone. Lead with the most important item (overspending or bills due), then the rest.
Use ONLY the numbers given in the stats, copied exactly as written (e.g. "$612.40"). Never compute new totals, never estimate, never round differently.
Skip sections that are empty. No investment or tax advice. No emoji.`;

const m = (x: Milli) => formatMilli(x);

/** Stats rendered as text for the model, with every amount pre-formatted. */
export function digestStatsText(s: DigestStats): string {
  const lines: string[] = [
    `Week: ${s.weekStart} to ${s.weekEnd}; month: ${formatMonth(s.month)}`,
    `Spent this month so far: ${m(s.spentMtdMilli)} of ${m(s.assignedMtdMilli)} assigned`,
    `Overspent categories: ${s.overspent.length ? s.overspent.map((o) => `${o.category} (${m(o.availableMilli)})`).join("; ") : "none"}`,
    `Unapproved transactions: ${s.unapprovedCount}; uncategorized: ${s.uncategorizedCount}`,
    `Unusual transactions: ${s.unusual.length ? s.unusual.map((u) => `${u.date} ${redactDigits(u.payee)} ${m(u.amountMilli)} (usually ${m(u.typicalMilli)})`).join("; ") : "none"}`,
    `New subscriptions: ${s.newSubscriptions.length ? s.newSubscriptions.map((n) => `${redactDigits(n.payee)} ${m(n.amountMilli)} ${n.cadence}`).join("; ") : "none"}`,
    `Price changes: ${s.priceChanges.length ? s.priceChanges.map((p) => `${redactDigits(p.payee)} ${m(p.fromMilli)} to ${m(p.toMilli)}`).join("; ") : "none"}`,
    `Bills due in the next 7 days: ${s.billsDue.length ? s.billsDue.map((b) => `${b.date} ${redactDigits(b.payee)} ${m(b.amountMilli)}`).join("; ") : "none"}`,
    `Net worth: ${s.netWorth ? `${m(s.netWorth.currentMilli)}, change ${formatMilli(s.netWorth.changeMilli, { sign: "always" })} since ${s.netWorth.sinceDate}` : "unavailable"}`,
  ];
  return lines.join("\n");
}

/** All dollar strings the stats contain, in the forms the model may legitimately copy. */
function allowedAmounts(s: DigestStats): Set<string> {
  const vals: Milli[] = [s.spentMtdMilli, s.assignedMtdMilli];
  for (const o of s.overspent) vals.push(o.availableMilli);
  for (const u of s.unusual) vals.push(u.amountMilli, u.typicalMilli);
  for (const n of s.newSubscriptions) vals.push(n.amountMilli);
  for (const p of s.priceChanges) vals.push(p.fromMilli, p.toMilli);
  for (const b of s.billsDue) vals.push(b.amountMilli);
  if (s.netWorth) vals.push(s.netWorth.currentMilli, s.netWorth.changeMilli);
  const out = new Set<string>();
  for (const v of vals) {
    const abs = formatMilli(v, { sign: "never" });
    out.add(abs);
    out.add(abs.replace(/\.00$/, ""));
    out.add(formatMilli(v, { sign: "never", cents: false }));
  }
  return out;
}

/** True when every "$x" figure in text appears in the stats. */
export function amountsAreGrounded(text: string, s: DigestStats): boolean {
  const allowed = allowedAmounts(s);
  for (const match of text.matchAll(/\$\d[\d,]*(?:\.\d{2})?/g)) {
    if (!allowed.has(match[0])) return false;
  }
  return true;
}

export function deterministicDigest(s: DigestStats): Digest {
  const parts: string[] = [];
  const push: string[] = [];
  parts.push(`**${formatMonth(s.month)} so far:** spent ${m(s.spentMtdMilli)} of ${m(s.assignedMtdMilli)} assigned.`);
  push.push(`Spent ${m(s.spentMtdMilli)} of ${m(s.assignedMtdMilli)}.`);
  if (s.overspent.length) {
    parts.push(`**Overspent:** ${s.overspent.map((o) => `${o.category} (${m(o.availableMilli)})`).join(", ")}.`);
    push.push(`${s.overspent.length} overspent.`);
  }
  if (s.billsDue.length) {
    parts.push(`**Bills due this week:** ${s.billsDue.map((b) => `${b.payee} ${m(b.amountMilli)} on ${b.date}`).join(", ")}.`);
    push.push(`${s.billsDue.length} bill${s.billsDue.length === 1 ? "" : "s"} due.`);
  }
  if (s.unapprovedCount || s.uncategorizedCount) {
    parts.push(`**To review:** ${s.unapprovedCount} unapproved, ${s.uncategorizedCount} uncategorized.`);
    push.push(`${s.unapprovedCount} to review.`);
  }
  if (s.unusual.length) {
    parts.push(`**Unusual:** ${s.unusual.map((u) => `${u.payee} ${m(u.amountMilli)} (usually ${m(u.typicalMilli)})`).join(", ")}.`);
  }
  if (s.newSubscriptions.length) {
    parts.push(`**New subscriptions:** ${s.newSubscriptions.map((n) => `${n.payee} ${m(n.amountMilli)} ${n.cadence}`).join(", ")}.`);
  }
  if (s.priceChanges.length) {
    parts.push(`**Price changes:** ${s.priceChanges.map((p) => `${p.payee} ${m(p.fromMilli)} to ${m(p.toMilli)}`).join(", ")}.`);
  }
  if (s.netWorth) {
    parts.push(`**Net worth:** ${m(s.netWorth.currentMilli)} (${formatMilli(s.netWorth.changeMilli, { sign: "always" })} since ${s.netWorth.sinceDate}).`);
  }
  let pushText = push.join(" ");
  if (pushText.length > 180) pushText = `${pushText.slice(0, 179)}…`;
  return { title: `Week of ${s.weekStart}`, pushText, body: parts.join("\n\n"), source: "deterministic" };
}

/** Generate the digest with Haiku when available; deterministic fallback otherwise. */
export async function generateDigest(ai: AiClient | null, stats: DigestStats, opts: { signal?: AbortSignal } = {}): Promise<Digest> {
  if (!ai || !(await ai.isAvailable("digest"))) return deterministicDigest(stats);
  try {
    const msg = await ai.create(
      "digest",
      {
        model: ai.models.digest,
        max_tokens: 1024,
        system: DIGEST_SYSTEM,
        messages: [{ role: "user", content: `Write this week's digest from these stats:\n\n${digestStatsText(stats)}` }],
        output_config: { effort: "low", format: { type: "json_schema", schema: DIGEST_SCHEMA } },
      },
      opts.signal ? { signal: opts.signal } : {},
    );
    if (msg.stop_reason !== "end_turn") return deterministicDigest(stats);
    const parsed = DigestOutputSchema.safeParse(JSON.parse(textOf(msg)));
    if (!parsed.success) return deterministicDigest(stats);
    const { title, push_text, body } = parsed.data;
    if (!amountsAreGrounded(`${title} ${push_text} ${body}`, stats)) return deterministicDigest(stats);
    return {
      title: title.trim().slice(0, 60),
      pushText: push_text.trim().length > 180 ? `${push_text.trim().slice(0, 179)}…` : push_text.trim(),
      body: body.trim(),
      source: "ai",
    };
  } catch {
    return deterministicDigest(stats);
  }
}
